svg.script:
//
    (function() {
      // DOM Elements Cache
      var btn1 = document.getElementById('a12p5h-btn-mode1');
      var btn2 = document.getElementById('a12p5h-btn-mode2');
      var btn3 = document.getElementById('a12p5h-btn-mode3');

      var grpHand = document.getElementById('a12p5h-group-examiner-hand');
      var grpCoccyxRepose = document.getElementById('a12p5h-group-coccyx-repose');
      var grpCoccyxRetro = document.getElementById('a12p5h-group-coccyx-retro');

      var lineCd = document.getElementById('a12p5h-line-cd-wrap');
      var lineCo = document.getElementById('a12p5h-line-co-wrap');
      var lineOutletRep = document.getElementById('a12p5h-line-outlet-rep-wrap');
      var lineOutletRet = document.getElementById('a12p5h-line-outlet-ret-wrap');

      var pnlHead = document.getElementById('a12p5h-pnl-head');
      var m1Val = document.getElementById('a12p5h-m1-val');
      var m1Sub = document.getElementById('a12p5h-m1-sub');
      var m2Val = document.getElementById('a12p5h-m2-val');
      var m2Sub = document.getElementById('a12p5h-m2-sub');

      var c1Title = document.getElementById('a12p5h-c1-title');
      var c1Desc = document.getElementById('a12p5h-c1-desc');
      var c2Title = document.getElementById('a12p5h-c2-title');
      var c2Desc = document.getElementById('a12p5h-c2-desc');

      var tooltip = document.getElementById('a12p5h-tooltip');
      var ttText = document.getElementById('a12p5h-tt-text');
      var ttRect = document.getElementById('a12p5h-tt-rect');
      var svgContainer = document.getElementById('a12p5h-svg-container');

      // State Machine Handler
      function setMode(mode) {
        // Reset Button Classes
        btn1.classList.remove('a12p5h-active');
        btn2.classList.remove('a12p5h-active');
        btn3.classList.remove('a12p5h-active');

        if (mode === 1) {
          btn1.classList.add('a12p5h-active');

          // Show Hand & Inlet measures; Hide retropulsion coccyx
          grpHand.classList.remove('a12p5h-hide');
          grpCoccyxRepose.classList.remove('a12p5h-hide');
          grpCoccyxRetro.classList.add('a12p5h-hide');

          lineCd.classList.remove('a12p5h-hide');
          lineCo.classList.remove('a12p5h-hide');
          lineOutletRep.classList.remove('a12p5h-hide');
          lineOutletRet.classList.add('a12p5h-hide');

          // Update Panel Content
          pnlHead.textContent = "1. PROMONTÓRIO & PELVIMETRIA";
          m1Val.textContent = "11,0 cm";
          m1Sub.textContent = "Conj. Obstétrica Útil (Fixo)";
          m2Val.textContent = "12,5 cm";
          m2Sub.textContent = "Conj. Diagonal (Toque Vaginal)";

          c1Title.textContent = "1. O PROMONTÓRIO COMO ANCORADOURO";
          c1Desc.innerHTML = "O <strong>Promontório Sacral (S1)</strong> é a projeção óssea posterior do estreito superior. Por ser rigidamente <strong style='color:#fbbf24;'>FIXO</strong>, serve de ponto de referência anatômica (régua de pelvimetria) e ancoradouro para promontofixação.";

          c2Title.textContent = "2. PELVIMETRIA CLÍNICA NO TOQUE";
          c2Desc.innerHTML = "No exame de toque vaginal, a mão alcança a ponta do promontório para medir a <em>Conjugata Diagonalis (12,5 cm)</em>. Subtrai-se 1,5 cm para estimar a <strong>Conjugata Obstétrica útil (11,0 cm)</strong>.";
        } 
        else if (mode === 2) {
          btn2.classList.add('a12p5h-active');

          // Hide Hand; Show Retropulsion Coccyx & Outlet expansion
          grpHand.classList.add('a12p5h-hide');
          grpCoccyxRepose.classList.remove('a12p5h-hide');
          grpCoccyxRetro.classList.remove('a12p5h-hide');

          lineCd.classList.add('a12p5h-hide');
          lineCo.classList.add('a12p5h-hide');
          lineOutletRep.classList.remove('a12p5h-hide');
          lineOutletRet.classList.remove('a12p5h-hide');

          // Update Panel Content
          pnlHead.textContent = "2. MOBILIDADE DO CÓCCIX";
          m1Val.textContent = "9,5 cm";
          m1Sub.textContent = "Diâmetro Basal em Repouso";
          m2Val.textContent = "11,5 cm";
          m2Sub.textContent = "Diâmetro Ampliado (+2,0 cm)";

          c1Title.textContent = "1. ARTICULAÇÃO SACROCOCCÍGEA";
          c1Desc.innerHTML = "Ao contrário do sacro fixo, a articulação sacrococcígea permite mobilidade. Em repouso, o cóccix projeta-se para a frente, limitando a saída anteroposterior em <strong style='color:#f59e0b;'>9,5 cm</strong>.";

          c2Title.textContent = "2. RETROPULSÃO NO DESPRENDIMENTO";
          c2Desc.innerHTML = "Na passagem da cabeça fetal pelo estreito inferior, o cóccix sofre <strong style='color:#34d399;'>retropulsão posterior</strong> de 1,5 a 2,0 cm, expandindo o diâmetro da saída para <strong>11,5 cm</strong> e facilitando o parto.";
        } 
        else if (mode === 3) {
          btn3.classList.add('a12p5h-active');

          // Show All Structures & Integrated View
          grpHand.classList.remove('a12p5h-hide');
          grpCoccyxRepose.classList.remove('a12p5h-hide');
          grpCoccyxRetro.classList.remove('a12p5h-hide');

          lineCd.classList.remove('a12p5h-hide');
          lineCo.classList.remove('a12p5h-hide');
          lineOutletRep.classList.remove('a12p5h-hide');
          lineOutletRet.classList.remove('a12p5h-hide');

          // Update Panel Content
          pnlHead.textContent = "3. DINÂMICA INTEGRADA DA PELVE";
          m1Val.textContent = "11,0 cm";
          m1Sub.textContent = "Entrada (Conj. Obstétrica Fixa)";
          m2Val.textContent = "11,5 cm";
          m2Sub.textContent = "Saída (Estreito Inf. Retropulsionado)";

          c1Title.textContent = "1. SÍNTESE ANATÔMICA PARA PROVA";
          c1Desc.innerHTML = "• <strong style='color:#fbbf24;'>Promontório (S1)</strong>: Fixo. Régua do estreito superior.<br/>• <strong style='color:#34d399;'>Cóccix</strong>: Móvel. Expande o estreito inferior no desprendimento.<br/>• <strong style='color:#38bdf8;'>Toque</strong>: CD - 1,5 cm = CO.";

          c2Title.textContent = "2. REGRA PRÁTICA RESIDÊNCIA";
          c2Desc.innerHTML = "A bacia obstétrica possui a entrada protegida por um diâmetro rígido fixo (CO = 11,0 cm) e a saída dinamicamente expansível pela retropulsão coccígea (9,5 ➔ 11,5 cm).";
        }
      }

      // Event Listeners for Buttons
      btn1.addEventListener('click', function() { setMode(1); });
      btn2.addEventListener('click', function() { setMode(2); });
      btn3.addEventListener('click', function() { setMode(3); });

      // Hotspot Tooltip Mouse/Touch Handlers
      var hotspots = [
        { id: 'a12p5h-hs-promontory', text: 'Promontório Sacral (S1) - Ponto FIXO' },
        { id: 'a12p5h-hs-coccyx', text: 'Cóccix - MÓVEL (Retropulsão +2,0 cm)' },
        { id: 'a12p5h-hs-outlet', text: 'Estreito Inferior (Saída Pelviana)' },
        { id: 'a12p5h-hs-exam', text: 'Exame de Toque Vaginal (Pelvimetria)' }
      ];

      hotspots.forEach(function(hs) {
        var el = document.getElementById(hs.id);
        if (!el) return;

        el.addEventListener('mouseenter', function(e) {
          showTooltip(hs.text, e);
        });
        el.addEventListener('mousemove', function(e) {
          moveTooltip(e);
        });
        el.addEventListener('mouseleave', function() {
          hideTooltip();
        });
        el.addEventListener('touchstart', function(e) {
          showTooltip(hs.text, e.touches[0]);
        }, { passive: true });
      });

      function showTooltip(text, e) {
        ttText.textContent = text;
        var textWidth = text.length * 7 + 20;
        ttRect.setAttribute('width', textWidth);
        ttRect.setAttribute('x', -textWidth / 2);
        tooltip.classList.remove('a12p5h-hide');
        moveTooltip(e);
      }

      function moveTooltip(e) {
        if (!svgContainer) return;
        var rect = svgContainer.getBoundingClientRect();
        var x = e.clientX - rect.left;
        var y = e.clientY - rect.top;
        tooltip.setAttribute('transform', 'translate(' + x + ', ' + (y - 15) + ')');
      }

      function hideTooltip() {
        tooltip.classList.add('a12p5h-hide');
      }

      // Initial Mode Setup
      setMode(1);
    })();
  //
